const months=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
const f=(m:string,r:number)=>`=COUNTIF(INDEX(${m}!$B$6:$AF$49,MATCH($O$3,${m}!$A$6:$A$49,0),0):INDEX(${m}!$B$6:$AF$49,MATCH($O$3,${m}!$A$6:$A$49,0)+1,0),$M${r})/2`;
const grid:string[][]=[];
for(let r=5;r<=12;r++)grid.push(months.map(m=>f(m,r)));
wb.getRange('Total!O5:Z12').setValues(grid);
wb.getRange('Total!N3:Z12')

